export const BACKUP_FORMAT = "zhijing408-local-backup";
export const BACKUP_VERSION = 1;
export const MAX_BACKUP_BYTES = 20 * 1024 * 1024;

const DATA_TYPES = Object.freeze({
  "relax-records": "array",
  "relax-mistakes": "array",
  "relax-ever-wrong": "array",
  "relax-seen": "array",
  "relax-groups": "array",
  "relax-bookmarks": "array",
  "relax-bookmark-times": "object",
  "relax-current-draft": "object",
  "relax408-saved-concepts": "array",
  "relax408-latest-result": "object",
  "tenzen-408-os-review-edits-v1": "object",
});

export const BACKUP_KEYS = Object.freeze(Object.keys(DATA_TYPES));

function validateValue(key, value) {
  const kind = DATA_TYPES[key];
  if (!kind) throw new Error(`备份包含不支持的数据项：${key}`);
  if (
    kind === "array"
      ? !Array.isArray(value)
      : !value || typeof value !== "object" || Array.isArray(value)
  ) {
    throw new Error(`备份数据格式有误：${key}`);
  }
}

export function createBackup(storage, now = new Date()) {
  const data = {};
  for (const key of BACKUP_KEYS) {
    const raw = storage.getItem(key);
    if (raw === null) continue;
    const value = JSON.parse(raw);
    validateValue(key, value);
    data[key] = value;
  }
  return {
    format: BACKUP_FORMAT,
    version: BACKUP_VERSION,
    exportedAt: now.toISOString(),
    data,
  };
}

export function parseBackup(text) {
  if (new TextEncoder().encode(text).length > MAX_BACKUP_BYTES)
    throw new Error("备份文件超过 20 MB");
  let backup;
  try {
    backup = JSON.parse(text);
  } catch {
    throw new Error("文件不是有效的 JSON");
  }
  if (backup?.format !== BACKUP_FORMAT || backup.version !== BACKUP_VERSION) {
    throw new Error("不是受支持的智镜 408 备份文件");
  }
  if (
    !backup.data ||
    typeof backup.data !== "object" ||
    Array.isArray(backup.data)
  ) {
    throw new Error("备份缺少数据");
  }
  for (const [key, value] of Object.entries(backup.data))
    validateValue(key, value);
  return backup;
}

export function applyBackup(storage, backup) {
  const snapshot = Object.fromEntries(
    BACKUP_KEYS.map((key) => [key, storage.getItem(key)]),
  );
  const next = Object.fromEntries(
    BACKUP_KEYS.map((key) => [
      key,
      Object.prototype.hasOwnProperty.call(backup.data, key)
        ? JSON.stringify(backup.data[key])
        : null,
    ]),
  );
  try {
    for (const key of BACKUP_KEYS) {
      if (next[key] === null) storage.removeItem(key);
      else storage.setItem(key, next[key]);
    }
  } catch (error) {
    for (const key of BACKUP_KEYS) {
      try {
        if (snapshot[key] === null) storage.removeItem(key);
        else storage.setItem(key, snapshot[key]);
      } catch {}
    }
    throw error;
  }
}
