import { jsx, jsxs } from "react/jsx-runtime";
import { OPTION_MARKS } from "./marks.js";

export function OptionChoice({
  questionId,
  optionKey,
  text,
  imageOnly,
  answer,
  mark,
  onSelect,
  onMark,
}) {
  return jsxs("div", {
    className: `option-entry ${mark ? `mark-${mark}` : ""}`,
    children: [
      jsxs("button", {
        type: "button",
        className: `answer-choice ${answer === optionKey ? "selected" : ""}`,
        "aria-pressed": answer === optionKey,
        "aria-label": imageOnly ? `选择 ${optionKey}` : undefined,
        onClick: onSelect,
        children: imageOnly
          ? [optionKey, jsx("i", { children: "✓" })]
          : [
              jsx("b", { children: optionKey }),
              jsx("span", { children: text }),
              jsx("i", { children: "✓" }),
            ],
      }),
      jsxs("div", {
        className: "option-mark-controls",
        "aria-label": `选项 ${optionKey} 标记`,
        children: Object.entries(OPTION_MARKS).map(([kind, label]) =>
          jsx(
            "button",
            {
              type: "button",
              className: mark === kind ? "active" : "",
              "aria-pressed": mark === kind,
              "aria-label": `${label}选项 ${optionKey}`,
              title: `${label}选项 ${optionKey}`,
              onClick: () => onMark(kind),
              children: label,
            },
            kind,
          ),
        ),
      }),
    ],
  });
}
