export const OPTION_MARKS = Object.freeze({
  eliminated: "排除",
  unsure: "存疑",
});

export function getOptionMark(marks, questionId, optionKey) {
  return marks?.[questionId]?.[optionKey] ?? null;
}

export function toggleOptionMark(marks, questionId, optionKey, kind) {
  if (!Object.prototype.hasOwnProperty.call(OPTION_MARKS, kind))
    throw new Error(`Unknown option mark: ${kind}`);
  const nextQuestion = { ...(marks[questionId] ?? {}) };
  if (nextQuestion[optionKey] === kind) {
    delete nextQuestion[optionKey];
  } else {
    nextQuestion[optionKey] = kind;
  }
  const next = { ...marks };
  if (Object.keys(nextQuestion).length) next[questionId] = nextQuestion;
  else delete next[questionId];
  return next;
}

export function readOptionMarks(value) {
  if (!value || typeof value !== "object" || Array.isArray(value)) return {};
  return Object.fromEntries(
    Object.entries(value).flatMap(([questionId, choices]) => {
      if (!choices || typeof choices !== "object" || Array.isArray(choices))
        return [];
      const marks = Object.fromEntries(
        Object.entries(choices).filter(([, kind]) =>
          Object.prototype.hasOwnProperty.call(OPTION_MARKS, kind),
        ),
      );
      return Object.keys(marks).length ? [[questionId, marks]] : [];
    }),
  );
}
